cd /app/Resources/Textures/Structures/Doors/Airlocks; for f in Effects/airlock-effects-firelock.rsi/{closing,opening}_unlit.png Standard/firelock-base.rsi/{closing,opening}.png Glass/firelock-base.rsi/{closing,opening}.png; do ffmpeg -v error -y -i $f -f rawvideo -pix_fmt rgba /tmp/$(echo $f|tr / _).raw; ffprobe -v error -show_entries stream=width,height -of csv $f; done
python3 - <<'E'
import glob
def load(n,w=480,h=128):
    d=open('/tmp/'+n.replace('/','_')+'.raw','rb').read()
    return d,w,h
def frame(d,w,fx,fy):
    return bytes(b for y in range(32) for b in d[((fy*32+y)*w+fx*32)*4:((fy*32+y)*w+fx*32+32)*4])
def bbox(fr):
    pts=[(i%32,i//32) for i in range(1024) if fr[i*4+3]>0]
    if not pts: return None
    xs=[p[0] for p in pts];ys=[p[1] for p in pts]
    return min(xs),min(ys),max(xs),max(ys)
for pre in ['Effects/airlock-effects-firelock.rsi/%s_unlit.png','Standard/firelock-base.rsi/%s.png','Glass/firelock-base.rsi/%s.png']:
    c,_,_=load(pre%'closing'); o,_,_=load(pre%'opening')
    print(pre)
    for dy in range(4):
        diffs=[k for k in range(15) if frame(c,480,k,dy)!=frame(o,480,14-k,dy)]
        print(' dir',dy,'diff frames',diffs)
        if diffs:
            for k in diffs: print('   ',k,bbox(frame(c,480,k,dy)),bbox(frame(o,480,14-k,dy)))
E

